fn find_first_occurrence(arr: &Vec<i32>, target: i32) -> Option<usize> {
    let mut lo: usize = 0;
    let mut hi: usize = arr.len(); // search in [lo, hi)

    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if arr[mid] < target {
            lo = mid + 1;
        } else {
            // arr[mid] >= target: keep mid in the search space
            hi = mid;
        }
    }

    if lo < arr.len() && arr[lo] == target {
        Some(lo)
    } else {
        None
    }
}